// Skip PRs already reviewed at their current head sha (workflow static data).
const store = $getWorkflowStaticData('global');
const reviewed = store.reviewed || {};
const out = [];
for (const item of $input.all()) {
  const pr = item.json;
  const key = String(pr.number);
  if (reviewed[key] === pr.head.sha) continue;
  out.push({ json: pr });
}
return out;

// Map the reviewer verdict to a provider-agnostic outcome.
// approve/comment -> success; request-changes -> failure (a cited blocker should block).
const content = $('Review').item.json.choices[0].message.content || '';
const verdictLine = content.split('\n').find((l) => /VERDICT\s*:/i.test(l)) || '';
const verdict = /request-changes/i.test(verdictLine) ? 'request-changes' : /approve/i.test(verdictLine) ? 'approve' : 'comment';
const state = verdict === 'request-changes' ? 'failure' : 'success';
const sha = $('List open PRs').item.json.head.sha;
return [{ json: { sha, verdict, body: { state, context: 'n8n-reviewer', description: ('reviewer: ' + verdict).slice(0, 140) } } }];

// Emit a PLATFORM-NEUTRAL event. Add channels/deployment at the `Notify (swap point)` node.
const pr = $('List open PRs').item.json;
const content = $('Review').item.json.choices[0].message.content || '';
const lines = content.split('\n');
const verdictLine = lines.find((l) => /VERDICT\s*:/i.test(l)) || 'VERDICT: (unknown)';
const verdict = /request-changes/i.test(verdictLine) ? 'request-changes' : /approve/i.test(verdictLine) ? 'approve' : 'comment';
const findings = lines.filter((l) => /^\s*-\s*\[/.test(l)).slice(0, 5).join('\n');
const text = ['PR #' + pr.number + ' ' + pr.title, (pr.user && pr.user.login ? pr.user.login : '') + ' @ ' + String(pr.head.sha).slice(0, 7), 'Verdict: ' + verdict, findings ? 'Findings:\n' + findings : ''].filter(Boolean).join('\n');
return [{ json: { channel: 'none', event: 'pr-review', title: 'PR #' + pr.number + ' ' + pr.title, text, url: pr.html_url, verdict, pr: pr.number, sha: pr.head.sha } }];

// Record the reviewed head sha so the next run skips it.
const store = $getWorkflowStaticData('global');
store.reviewed = store.reviewed || {};
for (const item of $input.all()) {
  const pr = $('List open PRs').item.json;
  store.reviewed[String(pr.number)] = pr.head.sha;
}
return $input.all();
